export function escapeHTML(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function contactLink(topic='General enquiry',extra={}){const p=new URLSearchParams({topic,...extra});return '#contact?'+p.toString();}
export function parseRoute(hash){const text=String(hash||'').replace(/^#/,'');const [path,query='']=text.split('?');const [candidate,detail]=path.split('/');const view=Object.hasOwn(sections,candidate)?candidate:'home';return {view,detail:detail||'',params:new URLSearchParams(query)};}
const eyebrow=(number,label)=>`<span class="eyebrow"><span class="red">${number}</span>${label}</span>`;
const action=(label,href)=>`<a class="action" href="${escapeHTML(href)}">${label}<span aria-hidden="true">↗</span></a>`;
const back=(label,href)=>`<a class="back-link" href="${href}"><span aria-hidden="true">←</span>${label}</a>`;
const title=text=>`<h1 class="page-title" tabindex="-1">${text}</h1>`;
const row=(name,description,href)=>`<a class="row-link" href="${href}"><div><h3>${name}</h3><p>${description}</p></div><span aria-hidden="true">↗</span></a>`;

const external=(label,href,extra='')=>`<a ${extra} href="${escapeHTML(href)}" target="_blank" rel="noopener noreferrer">${label}<span aria-hidden="true">↗</span><span class="sr-only"> (opens in a new tab)</span></a>`;
const genres=a=>`<div class="genre-tags">${a.genres.map(g=>`<span>${g}</span>`).join('')}</div>`;
export function renderArtistCard(slug,a){return `<a href="#roster/${slug}" class="artist-entry artist-card"><img class="roster-photo" src="${a.portrait}" alt="${a.name} artist portrait" width="850" height="1095" decoding="async"><div class="artist-card-copy"><span class="artist-index">DJ / PRODUCER · ${a.origin.toUpperCase()}</span><strong class="artist-name">${a.name}</strong><span class="artist-card-base">Based in ${a.base}</span>${genres(a)}<p>${a.intro}</p><span class="card-action">Artist profile & bookings <b>↗</b></span></div></a>`;}
export function renderPins(route){
 if(route.view==='roster'){const a=artists[route.detail]||artists['pa-ngu'];return `<a class="globe-pin artist-pin" href="#roster/pa-ngu" data-lon="${a.lon}" data-lat="${a.lat}" aria-label="Open PA NGU artist profile, Zimbabwe"><span class="pin-media"><img src="${a.pin}" alt="" width="280" height="258" decoding="async" fetchpriority="high"></span><strong>PA NGU</strong><small>Zimbabwe · DJ / Producer</small><span class="pin-stem"></span></a>`;}
 if(route.view==='presents'){return Object.entries(network).map(([code,c],i)=>{const image=i%2?'assets/event-room-pin.webp':'assets/event-crowd-pin.webp';return `<a class="globe-pin network-pin" data-lon="${c.lon}" data-lat="${c.lat}" data-country="${code}" href="#presents/${events[route.detail]?route.detail:'gungano-live'}?region=${code}" aria-label="Explore ${c.name}, planned event region. Stock event inspiration."><span class="pin-media"><img src="${image}" alt="" width="250" height="200" decoding="async" loading="eager"></span><strong>${c.name}</strong><small>Route in development</small><span class="pin-stem"></span></a>`;}).join('');}
 return '';
}
export function renderView(route){
 const {view,detail}=route;
 if(view==='about')return `${eyebrow('01','About ARCWORC')}${title('An independent<br><em>creative ecosystem.</em>')}<p class="lead">Music, talent, experiences and ideas.<br>Connected through ARCWORC.</p><p>ARCWORC is the parent identity for a growing family of creative practices and brands. Our work connects artist representation, music programming, live experiences, creative production, digital work and education.</p><p>The agency helps artists reach the right stages and helps venues and promoters find the right talent. Our services bring music direction, brand identity, design and project thinking into a coordinated brief.</p><p>Through ARCWORC Presents, we develop distinct ways for people to gather: GUNGANO label showcases, invitation-only SOMA and the collective experience of PAMOJA. Each has its own purpose and atmosphere.</p><p>Our wider ecosystem includes GUNGANO Records, LYNNK Marketplace, LYNNK ENGINE, DOGON and the planned ARCWORC Academy. Their identities remain independent, with connections across music, culture, learning and creative technology.</p><h2 class="content-heading">From an idea to the audience</h2><p>Artist representation connects career direction with practical booking support: availability, promoter communication, performance briefs, advancing and release planning. For venues and hospitality spaces, we shape music identities, resident programmes and carefully paced line-ups.</p><p>Our event work covers concept development, talent selection, production coordination, supplier communication and project management. Creative briefs can bring together brand strategy, visual identity, graphic design, websites and digital experiences, with a consistent story across every touchpoint.</p><p>Across the wider group, the label supports recorded music, DOGON connects stories with audiences through publication and PR, LYNNK Marketplace connects creators with commerce and collaboration, and LYNNK ENGINE develops tools for independent-label operations. The Academy adds practical pathways into music and creative work.</p><div class="facts"><div><h3>Based in Cape Town.</h3><p>Rooted in African music and creative culture, with relationships that connect people across borders.</p></div><div><h3>Built around the brief.</h3><p>A booking, a venue, an event, a brand or a new venture. We connect the disciplines the work requires.</p></div></div><div class="action-row">${action('Explore our brands','#brands')}<a class="text-link" href="#roster">Our artist roster <span>↗</span></a></div>`;
 if(view==='roster'&&artists[detail]){const a=artists[detail];return `${back('Back to our artist roster','#roster')}${eyebrow('02','Artist profile · DJ / Producer')}${title(a.name)}${genres(a)}<div class="artist-profile-hero"><img src="${a.portrait}" alt="PA NGU portrait" width="850" height="1095" decoding="async"><div><span class="profile-origin">${a.origin} → ${a.base}</span><p class="lead">${a.intro}</p>${action('Book '+a.name,contactLink('Artist booking & management',{artist:a.name}))}</div></div><div class="artist-stats"><span><b>15+</b> Years in music</span><span><b>300+</b> Shows</span><span><b>50+</b> Releases</span></div><h2 class="content-heading">About the artist</h2>${a.bio.map(p=>`<p>${p}</p>`).join('')}<h2 class="content-heading">Listen & connect</h2><div class="artist-links">${a.links.map(([label,url])=>external(label,url)).join('')}</div><div class="action-row">${external('Download artist EPK',a.epk,'class="text-link" download')}${external('Watch a live set',a.live,'class="text-link"')}</div><h2 class="content-heading">Selected releases</h2><div class="release-list">${a.releases.map(([n,d])=>`<div><span>${n}</span><small>${d}</small></div>`).join('')}</div><h2 class="content-heading">Bookings & promoter information</h2><p>For availability, performance briefs and bookings, contact Clint Coetzee at <a href="mailto:clint@arcworc.com">clint@arcworc.com</a>. Include your event date, city, venue, expected audience, set format and available budget.</p><p>The EPK includes selected live experience, music links, technical requirements and booking information. Travel, technical and hospitality arrangements are discussed as part of the booking brief.</p><div class="action-row">${action('Enquire about '+a.name,contactLink('Artist booking & management',{artist:a.name}))}</div>`;}
 if(view==='roster')return `${eyebrow('02','Bookings & representation')}${title('Our artist<br><em>roster.</em>')}<p class="lead">Discover the artist, explore the music<br>and start a booking conversation.</p><div class="artist-grid">${Object.entries(artists).map(([slug,a])=>renderArtistCard(slug,a)).join('')}</div><p class="small-note">For venue programming, festivals, private events and brand experiences: <a href="mailto:clint@arcworc.com">clint@arcworc.com</a>.</p>`;
 if(view==='presents'&&events[detail]){const e=events[detail];const country=network[route.params.get('region')];return `${back('Back to Presents','#presents')}${eyebrow('03','ARCWORC Presents')}${title(e.name)}<span class="label-pill">${e.status}</span><p class="lead">${e.type}</p><p>${e.copy}</p><ul class="scope-list">${e.points.map(t=>`<li>${t}</li>`).join('')}</ul><p>${e.more}</p><h2 class="content-heading">One idea. Different places.</h2><p>Our roaming project connects music, local talent and new audiences across Africa. We are exploring Nigeria, Kenya, Zimbabwe and South Africa, shaping each edition with local collaborators, venues and communities.</p>${country?`<p class="location-selection">Exploring <strong>${country.name}</strong> · Route in development. Dates and venues will follow once confirmed.</p>`:'<p class="small-note">Locations are in development. Confirmed dates, venues and access details will be announced for each edition.</p>'}<div class="experience-gallery"><figure><img src="assets/event-crowd.webp" alt="A crowd beneath red concert lighting; stock atmosphere reference" width="1100" height="618" loading="lazy"><figcaption>Live energy · <a href="https://unsplash.com/photos/6kveU1lPbjA" target="_blank" rel="noopener noreferrer">Nicolás Flor / Unsplash ↗</a></figcaption></figure><figure><img src="assets/event-room.webp" alt="An audience beneath stage lights and a disco ball; stock atmosphere reference" width="600" height="900" loading="lazy"><figcaption>Shared moments · <a href="https://unsplash.com/photos/3Xbl9Rgf6hY" target="_blank" rel="noopener noreferrer">Brooke Balentine / Unsplash ↗</a></figcaption></figure></div><p class="small-note">Event atmosphere · Stock photography for inspiration.</p><div class="action-row">${action(e.name==='SOMA'?'Collaboration enquiries':'Discuss '+e.name,contactLink('Events & live experiences',{experience:e.name}))}</div>`;}
 if(view==='presents')return `${eyebrow('03','ARCWORC Presents')}${title('Music in<br><em>motion.</em>')}<p class="lead">Roaming experiences. Local connections.<br>A shared love of music.</p><p>We are developing a travelling programme of label showcases, invitation-only gatherings and collective experiences. The idea moves; each edition takes its character from the people, music and place it brings together.</p><p>Nigeria, Kenya, Zimbabwe and South Africa form our initial route in development. We are exploring local partnerships and spaces, with dates and venues announced as each edition is confirmed.</p><div class="countries" role="group" aria-label="Explore planned event regions">${Object.entries(network).map(([code,c])=>`<button class="country-button" data-country="${code}" aria-pressed="false">${c.name}</button>`).join('')}</div><div class="row-list">${Object.entries(events).map(([slug,e])=>row(e.name,e.type,'#presents/'+slug)).join('')}</div><p class="small-note">Choose a format or explore a region on the globe.<br>Map imagery: stock event inspiration · Route in development.</p>`;
 if(view==='services')return `${eyebrow('04','Services')}${title('What we<br><em>can do for you.</em>')}<p class="lead">Explore the scope, then tell us<br>where you want to begin.</p><div class="service-list">${services.map((s,i)=>`<details name="arcworc-services"><summary><span class="number">0${i+1}</span><h3>${s.name}</h3><span class="plus" aria-hidden="true"></span></summary><div class="service-detail"><p>${s.copy}</p><ul class="scope-list">${s.scope.map(t=>`<li>${t}</li>`).join('')}</ul><p>${s.result}</p><a class="text-link" href="${escapeHTML(contactLink(s.name))}">${s.action} <span>↗</span></a></div></details>`).join('')}</div>`;
 if(view==='brands'&&brands[detail]){const b=brands[detail];return `${back('Back to Our Brands','#brands')}${eyebrow('05','Our Brands')}${title(b.name)}<span class="meta-line">${b.type}</span><p class="lead">${b.copy}</p><p>${b.more}</p><div class="action-row">${b.external?external(b.linkText,b.external,'class="action"'):action(b.linkText,b.link)}<a class="text-link" href="${escapeHTML(contactLink(detail==='academy'?'Academy programme interest':'General enquiry',{brand:b.name}))}">${detail==='academy'?'Enquire about learning':'Connect about '+escapeHTML(b.name)} <span>↗</span></a></div>`;}
 if(view==='brands')return `${eyebrow('05','Our Brands')}${title('The ARCWORC ecosystem.')}<p class="lead">Independent identities across music,<br>media, technology and learning.</p><p>Explore what each brand does and how to connect with its work.</p><div class="row-list brand-list">${Object.entries(brands).map(([slug,b])=>`<a class="row-link" href="#brands/${slug}"><div><span class="brand-type">${b.type}</span><h3>${b.name}</h3><p>${b.copy}</p><span class="brand-read-more">${slug==='academy'?'Discover the Academy':'Read about '+b.name} ↗</span></div><span aria-hidden="true">↗</span></a>`).join('')}</div><div class="action-row">${action('Find your learning pathway','#academy')}<a class="text-link" href="#contact">Discuss a collaboration <span>↗</span></a></div>`;
 if(view==='academy'&&programmes.some(p=>p.slug===detail)){const p=programmes.find(p=>p.slug===detail);return `${back('Back to the Academy','#academy')}${eyebrow('06','Planned programme')}${title(p.name)}<p class="lead">${p.intro}</p><span class="label-pill">Beginner → developing → advanced</span><h2 class="content-heading">What you can explore</h2><ul class="scope-list">${p.scope.map(t=>`<li>${t}</li>`).join('')}</ul><h2 class="content-heading">Put it into practice</h2><p>${p.outcome}</p><h2 class="content-heading">A pathway around your level</h2><p>Tell us your experience, equipment and goals so we can discuss a suitable starting point. These are planned learning pathways; dates, duration, delivery format, course fees and availability will be confirmed before enrolment.</p><div class="programme-guide"><h3>Programme guide</h3><p>The detailed course document is being prepared. It will be available to download here once published.</p><button type="button" disabled>Download guide · coming soon</button></div><div class="action-row">${action('Enquire about this programme',contactLink('Academy programme interest',{course:p.name}))}</div>`;}
 if(view==='academy')return `${eyebrow('06','ARCWORC Academy')}${title('Learn. Create.<br><em>Develop your craft.</em>')}<p class="lead">Practical pathways into music, performance,<br>sound and creative work.</p><p>From your first session to a more developed practice, explore the skills behind making music and reaching an audience. Planned pathways span FL Studio, Ableton Live, DJ performance, sound engineering, artist development and music business.</p><p>Choose a discipline to read about its scope and progression. Programmes are in development; dates and enrolment details will be confirmed before bookings open.</p><div class="course-grid">${programmes.map((p,i)=>`<a class="course-link" href="#academy/${p.slug}"><small>0${i+1} / PLANNED PROGRAMME</small><h3>${p.name}</h3><span>Explore the programme ↗</span></a>`).join('')}</div><div class="programme-guide"><h3>Take a closer look</h3><p>A downloadable Academy programme guide is being prepared. In the meantime, each programme above explains its proposed scope and learning pathway.</p><button type="button" disabled>Programme guide · coming soon</button></div><div class="action-row">${action('Enquire about the Academy',contactLink('Academy programme interest'))}</div>`;
 if(view==='contact')return `${eyebrow('07','Make a connection')}${title('Talk to ARCWORC.')}<p class="lead">Bookings, creative briefs, partnerships<br>and new ideas. Find the right contact.</p><div class="contact-addresses"><a href="mailto:clint@arcworc.com"><small>ARTIST BOOKINGS / CLINT COETZEE</small>clint@arcworc.com ↗</a><a href="mailto:dean@arcworc.com"><small>COLLABORATIONS / DEAN</small>dean@arcworc.com ↗</a></div><form id="contact-form"><label class="form-honeypot" aria-hidden="true">Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label><div class="form-row"><label>Your name<input name="name" autocomplete="name" required placeholder="Name and surname"></label><label>Email address<input name="email" type="email" autocomplete="email" required placeholder="you@company.com"></label></div><label>Organisation <span class="optional">(optional)</span><input name="company" autocomplete="organization" placeholder="Company / venue / project"></label><label>What can we help with?<select name="topic" id="topic" required><option value="">Choose a starting point</option>${[...services.map(s=>s.name),'Academy programme interest','General enquiry'].map(t=>`<option>${t}</option>`).join('')}</select></label><div id="booking-fields" hidden><div class="form-row"><label>Event date <span class="optional">(if known)</span><input type="date" name="date"></label><label>Venue / city <span class="optional">(if known)</span><input name="venue" placeholder="Where is your event?"></label></div></div><label>Your idea<textarea name="message" id="message" rows="3" required placeholder="Tell us a little about what you have in mind."></textarea></label><p class="form-note">Your enquiry goes directly to the relevant ARCWORC inbox. We use your details to respond to this enquiry.</p><button type="submit" class="action">Send your enquiry <span>↗</span></button><p id="form-status" class="form-status" role="status" hidden></p><div id="email-fallback" hidden><a id="direct-email" class="text-link" href="mailto:dean@arcworc.com">Send from your email app ↗</a><label>Your enquiry<textarea id="email-copy" rows="7" readonly></textarea></label><button type="button" id="copy-enquiry" class="text-link">Copy enquiry <span>↗</span></button></div></form>`;
 return '';
}
